    function run(
        string calldata name_,
        string calldata symbol_,
        uint256 maintenance_,
        uint256 makerLimit_
    ) public {
        require(bytes(name_).length > 0);
        IProduct.ProductInfo memory info;
        info.name = name_;
        info.symbol = symbol_;
        info.oracle = IOracleProvider(address(new OracleStub()));
        info.maintenance = UFixed18.wrap(maintenance_);
        info.fundingFee = UFixed18.wrap(0);
