contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string calldata name_,
        string calldata symbol_,
        uint256 maintenanceRaw_,
        uint256 fundingFeeRaw_,
        uint256 makerFeeRaw_,
        uint256 takerFeeRaw_,
        uint256 positionFeeRaw_,
        uint256 makerLimitRaw_,
        uint256 minRate_,
        uint256 maxRate_,
        uint256 targetRate_,
        uint256 targetUtilization_
    ) public {
        // bounded fee params so UParamProvider validation passes
        require(fundingFeeRaw_ <= 1e18 && makerFeeRaw_ <= 1e18 && takerFeeRaw_ <= 1e18 && positionFeeRaw_ <= 1e18);
        require(minRate_ <= type(int128).max && maxRate_ <= type(int128).max && targetRate_ <= type(int128).max);
        require(targetUtilization_ <= type(uint128).max);
        require(maintenanceRaw_ <= type(int256).max && makerLimitRaw_ <= type(int256).max);

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(minRate_)),
            maxRate: PackedFixed18.wrap(int128(maxRate_)),
            targetRate: PackedFixed18.wrap(int128(targetRate_)),
            targetUtilization: PackedUFixed18.wrap(uint128(targetUtilization_))
        });

        PayoffDefinition memory payoff = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.Linear,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.Long,
            data: bytes30(0)
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name_,
            symbol: symbol_,
            payoffDefinition: payoff,
            oracle: IOracleProvider(address(0)),
            maintenance: UFixed18.wrap(maintenanceRaw_),
            fundingFee: UFixed18.wrap(fundingFeeRaw_),
            makerFee: UFixed18.wrap(makerFeeRaw_),
            takerFee: UFixed18.wrap(takerFeeRaw_),
            positionFee: UFixed18.wrap(positionFeeRaw_),
            makerLimit: UFixed18.wrap(makerLimitRaw_),
            utilizationCurve: curve
        });

        bool firstReverted;
        try c.initialize(info) { firstReverted = false; } catch { firstReverted = true; }

        require(!firstReverted);

        bool secondReverted;
        try c.initialize(info) { secondReverted = false; } catch { secondReverted = true; }

        string memory storedName = c.name();
        string memory storedSymbol = c.symbol();
        UFixed18 storedMaintenance = c.maintenance();

        assert(
            secondReverted
            && keccak256(abi.encodePacked(storedName)) == keccak256(abi.encodePacked(name_))
            && keccak256(abi.encodePacked(storedSymbol)) == keccak256(abi.encodePacked(symbol_))
            && UFixed18.unwrap(storedMaintenance) == maintenanceRaw_
        );
    }

    receive() external payable {}
}

