        uint256 versionAfter = c.latestVersion();
        PrePosition memory preAfter = c.pre();

        assert(
            openReverted
            && versionAfter == 0
            && preAfter.oracleVersion == 0
            && UFixed18.unwrap(preAfter.openPosition.maker) == 0
            && UFixed18.unwrap(preAfter.openPosition.taker) == 0
        );
    }

    receive() external payable {}
}

