contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(string memory name1, string memory symbol1, string memory name2, string memory symbol2) public {
        IProduct.ProductInfo memory info;
        info.name = name1;
        info.symbol = symbol1;
        info.oracle = IOracleProvider(address(this));

        bool reverted2;
        try c.initialize(info) {
            IProduct.ProductInfo memory info2;
            info2.name = name2;
            info2.symbol = symbol2;
            info2.oracle = IOracleProvider(address(this));
            try c.initialize(info2) { reverted2 = false; } catch { reverted2 = true; }
        } catch {
            // first initialize also reverted; second one must revert too
            try c.initialize(info) { assert(false); } catch { assert(true); }
            return;
        }
        assert(reverted2 && keccak256(bytes(c.name())) == keccak256(bytes(name1)) && keccak256(bytes(c.symbol())) == keccak256(bytes(symbol1)));
    }

    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

